#include "config.h"
#include "DriftstackWebGLReadPixelsOverride.h"

#if PLATFORM(DRIFTSTACK)

#include <cstdlib>
#include <wtf/HashMap.h>
#include <wtf/Lock.h>
#include <wtf/NeverDestroyed.h>
#include <wtf/RefCounted.h>
#include <wtf/RefPtr.h>
#include <wtf/StdLibExtras.h>
#include <wtf/Vector.h>
#include <wtf/text/Base64.h>
#include <wtf/text/StringView.h>
#include <wtf/text/WTFString.h>

namespace WebCore {

namespace {
constexpr WebGLReadPixelsOverrideEntry kWebGLReadPixelsOverrideTableData[] = {
// V-375 AUTO-GEN BEGIN — kWebGLReadPixelsOverrideTableData
    {
        "iphone16pro_ios18_bs",
        "g5_triangle_clearcolor_256x256",
        256u, // canvasWidth
        256u, // canvasHeight
        0x1908u, // glFormat (GL_RGBA)
        0x1401u, // glType (GL_UNSIGNED_BYTE)
        262144u, // pixelByteCount
        "",
    },
// V-375 AUTO-GEN END — kWebGLReadPixelsOverrideTableData
};
class DecodedReadPixelsBytes : public RefCounted<DecodedReadPixelsBytes> {
public:
    static Ref<DecodedReadPixelsBytes> create() { return adoptRef(*new DecodedReadPixelsBytes); }
    Vector<uint8_t> bytes;
};

Lock& cacheLock()
{
    static NeverDestroyed<Lock> lock;
    return lock.get();
}

HashMap<const char*, RefPtr<DecodedReadPixelsBytes>>& cache()
{
    static NeverDestroyed<HashMap<const char*, RefPtr<DecodedReadPixelsBytes>>> map;
    return map.get();
}

RefPtr<DecodedReadPixelsBytes> decodeOnce(const char* base64Data)
{
    auto view = StringView::fromLatin1(base64Data);
    auto decoded = base64Decode(view, { Base64DecodeOption::ValidatePadding });
    if (!decoded)
        return nullptr;
    auto buf = DecodedReadPixelsBytes::create();
    buf->bytes = WTF::move(decoded.value());
    return buf;
}

std::span<const WebGLReadPixelsOverrideEntry> tableSpan()
{
    return std::span<const WebGLReadPixelsOverrideEntry>(kWebGLReadPixelsOverrideTableData);
}

} // anonymous

namespace Driftstack {

bool isWebGLReadPixelsOverrideEnabled()
{
    static const bool enabled = []() {
        const char* env = std::getenv("DRIFTSTACK_WEBGL_READPIXELS_OVERRIDE");
        return env && env[0] == '1';
    }();
    return enabled;
}

bool getWebGLReadPixelsOverrideBytes(uint32_t canvasWidth, uint32_t canvasHeight, uint32_t glFormat, uint32_t glType, std::span<const uint8_t>& outBytes)
{
    if (!canvasWidth || !canvasHeight)
        return false;
    for (const auto& entry : tableSpan()) {
        if (entry.canvasWidth != canvasWidth || entry.canvasHeight != canvasHeight)
            continue;
        if (entry.glFormat != glFormat || entry.glType != glType)
            continue;
        if (!entry.pixelBytesBase64)
            return false;
        Locker locker(cacheLock());
        auto& map = cache();
        auto it = map.find(entry.pixelBytesBase64);
        if (it == map.end()) {
            auto decoded = decodeOnce(entry.pixelBytesBase64);
            if (!decoded)
                return false;
            it = map.set(entry.pixelBytesBase64, decoded.copyRef()).iterator;
        }
        if (!it->value)
            return false;
        if (it->value->bytes.size() != entry.pixelByteCount)
            return false;
        outBytes = it->value->bytes.span();
        return true;
    }
    return false;
}

} // namespace Driftstack
} // namespace WebCore

#endif // PLATFORM(DRIFTSTACK)
